export const handler = async (input) => {
  const definitions = {
    external_supplier_openness: { maximum:25, points:{ OPEN:25, SUPPORTED:20, CLOSED:4, UNKNOWN:12 } },
    supplier_onboarding_accessibility: { maximum:20, points:{ OPEN:20, CONTACT_ROUTE:15, INVITATION_ONLY:4, CLOSED:0, UNKNOWN:10 } },
    buying_procurement_accessibility: { maximum:15, points:{ NAMED_VERIFIED:15, DEPARTMENT_VERIFIED:13, ROUTE_ONLY:9, CLOSED:2, UNKNOWN:7 } },
    product_category_buying_fit: { maximum:15, points:{ HIGH:15, MEDIUM:10, LOW:4, UNKNOWN:7 } },
    commercial_operational_feasibility: { maximum:15, points:{ COMPATIBLE:15, SUPPORTED:12, BARRIER:5, UNKNOWN:7 } },
    supplier_lock_in_barrier: { maximum:10, points:{ LOW:10, MODERATE:5, HIGH:0, UNKNOWN:5 } }
  };
  const dimensions = {};
  const reasonCodes = [];
  const missingEvidence = [];
  let total = 0;
  for (const [key, definition] of Object.entries(definitions)) {
    const fact = input.dimensions?.[key] || {};
    const state = String(fact.state || 'UNKNOWN').toUpperCase();
    const points = definition.points[state] ?? definition.points.UNKNOWN;
    const evidenceIds = Array.isArray(fact.evidence_ids) ? fact.evidence_ids.filter(Boolean) : [];
    const reason = fact.reason || `${key}:${state}`;
    const unknownFields = Array.isArray(fact.unknown_fields) ? fact.unknown_fields.filter(Boolean) : [];
    if (state === 'UNKNOWN') missingEvidence.push(...(unknownFields.length ? unknownFields : [key]));
    total += points;
    reasonCodes.push(`${key.toUpperCase()}_${state}`);
    dimensions[key] = { points, maximum:definition.maximum, state, reason, evidence_ids:evidenceIds, unknown_fields:unknownFields };
  }
  const score = Math.max(0, Math.min(100, Math.round(total)));
  const band = score >= 80 ? 'HIGH' : score >= 60 ? 'MEDIUM' : score >= 40 ? 'LOW_MEDIUM' : 'LOW';
  const fit = String(input.target_fit || 'LOW').toUpperCase();
  const matrix = fit === 'HIGH' ? (band === 'HIGH' ? 'HIGH_FIT_HIGH_ACCESS' : band === 'MEDIUM' || band === 'LOW_MEDIUM' ? 'HIGH_FIT_MEDIUM_ACCESS' : 'HIGH_FIT_LOW_ACCESS') : fit === 'MEDIUM' ? (band === 'HIGH' ? 'MEDIUM_FIT_HIGH_ACCESS' : band === 'MEDIUM' || band === 'LOW_MEDIUM' ? 'MEDIUM_FIT_MEDIUM_ACCESS' : 'LOW_PRIORITY') : 'LOW_PRIORITY';
  const relationship = String(input.relationship_status || 'NEW_PROSPECT').toUpperCase();
  let readiness = 'REVIEW';
  if (relationship === 'INTERNAL_EXISTING_CUSTOMER') readiness = 'EXISTING_CUSTOMER';
  else if (relationship === 'SUPPRESSED') readiness = 'SUPPRESSED';
  else if (relationship === 'HISTORICAL_CRM_LEAD' || relationship === 'HISTORICAL_CONTACTED_LEAD') readiness = 'HISTORICAL_REVIEW';
  else if (matrix === 'HIGH_FIT_LOW_ACCESS') readiness = 'STRATEGIC_LONG_SHOT';
  else if (!input.has_verified_decision_route) readiness = 'NEEDS_DECISION_MAKER';
  else if (!input.has_usable_contact_route) readiness = 'NEEDS_CONTACT_ROUTE';
  else if (!input.has_traceable_evidence || input.role_review_required) readiness = 'NEEDS_VERIFICATION';
  else if (band === 'LOW') readiness = fit === 'HIGH' ? 'STRATEGIC_LONG_SHOT' : 'REVIEW';
  else readiness = 'SALES_READY';
  return { cooperation_feasibility_score:score, feasibility_band:band, access_opportunity_matrix:matrix, opportunity_readiness:readiness, relationship_status:relationship, dimension_breakdown:dimensions, reason_codes:[...new Set(reasonCodes)], missing_evidence:[...new Set(missingEvidence)], rule_version:'cooperation-feasibility-v1' };
};
